// Mono metal-bell source positioned in the view, with restrained stereo early reflections.
export class SpatialBells{
 constructor(context,{base=new URL('../assets/',import.meta.url),fetcher=(...a)=>fetch(...a),file='bells.wav',level=.88}={}){if(!['bells.wav','bark.wav'].includes(file))throw Error('Invalid spatial effect');this.file=file;this.level=level;this.context=context;this.base=base;this.fetcher=fetcher;this.voices=new Set();this.token=0;this.enabled=false;this.muted=false;this.output=context.createGain();this.output.gain.value=0;this.output.connect(context.destination);this.room=context.createConvolver();const rate=context.sampleRate,impulse=context.createBuffer(2,Math.floor(rate*.48),rate);let seed=1973;for(let ch=0;ch<2;ch++){const data=impulse.getChannelData(ch);for(let i=0;i<data.length;i++){seed=seed*16807%2147483647;data[i]=(seed/1073741823.5-1)*Math.exp(-i/(rate*.095))*.14;}for(const[t,g]of[[.019,.5],[.031,.3],[.053,.18]])data[Math.floor((t+ch*.002)*rate)]+=g;}this.room.buffer=impulse;const wet=context.createGain();wet.gain.value=.15;this.room.connect(wet);wet.connect(this.output);}
 load(){return this.loading??=this.fetcher(new URL('orava/'+this.file,this.base)).then(async r=>{if(!r.ok)throw Error('Bell sound unavailable');return this.context.decodeAudioData(await r.arrayBuffer());}).then(buffer=>{this.buffer=buffer;return buffer;}).catch(e=>{this.loading=null;throw e;});}
 volume(){this.output.gain.setTargetAtTime(this.enabled&&!this.muted ? this.level : 0,this.context.currentTime,.008);}
 setMuted(value){this.muted=!!value;this.volume();}
 setEnabled(value){this.enabled=!!value;if(!value)this.stop();this.volume();}
 stop(){this.token++;for(const v of this.voices){try{v.source.stop();}catch{}v.source.disconnect();v.pan.disconnect();}this.voices.clear();}
 async ring(x,y,camera={x:0,y:0}){if(!this.enabled||this.muted)return false;const token=this.token,buffer=this.buffer||await this.load();if(token!==this.token||!this.enabled||this.muted)return false;if(this.voices.size>=8){const oldest=this.voices.values().next().value;oldest.source.stop();oldest.source.disconnect();oldest.pan.disconnect();this.voices.delete(oldest);}const source=this.context.createBufferSource(),pan=this.context.createPanner();source.buffer=buffer;pan.panningModel='HRTF';pan.distanceModel='inverse';pan.refDistance=1;pan.rolloffFactor=.25;pan.maxDistance=15;pan.positionX.value=Math.max(-2,Math.min(2,(x-camera.x-160)/85));pan.positionY.value=Math.max(-.8,Math.min(.8,(88-(y-camera.y))/110));pan.positionZ.value=-1.5;source.connect(pan);pan.connect(this.output);pan.connect(this.room);const voice={source,pan};this.voices.add(voice);source.onended=()=>{source.disconnect();pan.disconnect();this.voices.delete(voice);};source.start();this.lastPosition={x:pan.positionX.value,y:pan.positionY.value,z:-1.5};return true;}
}
